import { EventBus } from './EventBus';
import { Rng } from './rng';
import type { GameMap } from '../world/GameMap';
import { NavGrid } from '../world/NavGrid';
import { EntityManager } from '../entities/EntityManager';
import { PathService } from '../ai/PathService';
import { AnchorBfs } from '../ai/yieldSearch';
import type { AiContext } from '../ai/AiContext';
import { DoorSystem } from '../systems/DoorSystem';
import { LawSystem } from '../systems/LawSystem';
import { EconomySystem } from '../systems/EconomySystem';
import { CombatSystem } from '../systems/CombatSystem';
import { WarSystem } from '../systems/WarSystem';
import { UndergroundSystem } from '../systems/UndergroundSystem';
import { InsurgencySystem } from '../systems/InsurgencySystem';
import { LaborSystem } from '../systems/LaborSystem';
import { CrimeSystem } from '../systems/CrimeSystem';
import { ScannerSystem } from '../systems/ScannerSystem';
import { RosterSystem } from '../systems/Roster';
import { ElectionSystem } from '../systems/ElectionSystem';
import { FamilySystem } from '../systems/Families';
import { SecuritySystem } from '../systems/Security';
import { CwuHqSystem } from '../systems/CwuHq';
import { ArsenalSystem } from '../systems/Arsenal';
import { PrisonSystem } from '../systems/Prison';
import { StreetShops } from '../systems/StreetShops';
import { Housing } from '../systems/Housing';
import { Fence } from '../systems/Fence';
import { Routine } from '../systems/Routine';
import { Errands } from '../systems/Errands';
import { Brawls } from '../systems/Brawls';
import { GangSystem } from '../systems/Gangs';
import { StreetLifeSystem } from '../systems/StreetLife';
import { AcademySystem } from '../systems/Academy';
import { Staffing } from '../systems/Staffing';
import { Access } from '../systems/Access';
import { Radio } from '../systems/Radio';
import { Talk } from '../systems/Talk';

/** Опции сборки: игра включает всё; тесты выключают часть поведения (у него свой тест). */
export interface CreateWorldOptions {
  /** Общий ГСЧ мира (игра: seed карты; тесты: фиксированный). */
  rng: Rng;
  /** Распорядок дня (в тестах выключен — иначе ночью город спит). */
  routineEnabled?: boolean;
  /** Набор в академию (в тестах выключен — иначе лоялисты уходят учиться). */
  academyRecruiting?: boolean;
  /** Случайные уличные драки (в тестах выключены — у драк свой тест). */
  brawlsEnabled?: boolean;
}

/** Мир целиком: контекст ИИ и ссылки на все системы (для тика и тестов). */
export interface World {
  ctx: AiContext;
  doors: DoorSystem;
  law: LawSystem;
  economy: EconomySystem;
  combat: CombatSystem;
  underground: UndergroundSystem;
  war: WarSystem;
  insurgency: InsurgencySystem;
  labor: LaborSystem;
  crime: CrimeSystem;
  scanners: ScannerSystem;
  roster: RosterSystem;
  elections: ElectionSystem;
  street: StreetLifeSystem;
  families: FamilySystem;
  security: SecuritySystem;
  cwuHq: CwuHqSystem;
  arsenal: ArsenalSystem;
  prison: PrisonSystem;
  shops: StreetShops;
  housing: Housing;
  fence: Fence;
  gangs: GangSystem;
  routine: Routine;
  errands: Errands;
  brawls: Brawls;
  academy: AcademySystem;
  staffing: Staffing;
  access: Access;
  radio: Radio;
  talk: Talk;
}

/**
 * Единая сборка мира: карта → контекст ИИ → все системы и обратные связи между ними.
 * Один источник правды для игры и тестов: список систем и их связи заданы здесь,
 * а не в двух копиях (Game.setMap и simHarness), которые могли бы разойтись.
 *
 * Порядок постройки важен: базовые системы (двери, закон, экономика, бой) — до
 * контекста; системы контекста — после (им нужен контекст для спавна); поля war и
 * дальше заполняются сразу после постройки своей системы (тип не допускает null).
 */
export function createWorld(
  map: GameMap,
  nav: NavGrid,
  entities: EntityManager,
  bus: EventBus,
  opts: CreateWorldOptions,
): World {
  const rng = opts.rng;
  const doors = new DoorSystem(map, nav);
  const law = new LawSystem(map, nav, doors, entities, bus, rng);
  const economy = new EconomySystem(map, entities, bus, rng);
  const combat = new CombatSystem(map, entities, bus, rng, law);
  const ctx: AiContext = {
    map,
    nav,
    paths: new PathService(map, nav),
    bfs: new AnchorBfs(nav),
    entities,
    rng,
    player: null,
    time: 0,
    law,
    doors,
    bus,
    economy,
    combat,
    underground: new UndergroundSystem(map, nav, entities),
    war: null as unknown as WarSystem,
    insurgency: null as unknown as InsurgencySystem,
    labor: null as unknown as LaborSystem,
    crime: null as unknown as CrimeSystem,
    scanners: null as unknown as ScannerSystem,
    roster: null as unknown as RosterSystem,
    elections: null as unknown as ElectionSystem,
    street: null as unknown as StreetLifeSystem,
    families: null as unknown as FamilySystem,
    security: null as unknown as SecuritySystem,
    cwuHq: null as unknown as CwuHqSystem,
    arsenal: null as unknown as ArsenalSystem,
    prison: null as unknown as PrisonSystem,
    shops: null as unknown as StreetShops,
    housing: null as unknown as Housing,
    fence: null as unknown as Fence,
    gangs: null as unknown as GangSystem,
    routine: null as unknown as Routine,
    errands: null as unknown as Errands,
    brawls: null as unknown as Brawls,
    academy: null as unknown as AcademySystem,
    staffing: null as unknown as Staffing,
    access: null as unknown as Access,
    radio: null as unknown as Radio,
    talk: null as unknown as Talk,
  };
  ctx.routine = new Routine(ctx, opts.routineEnabled ?? true);
  ctx.errands = new Errands(ctx);
  const war = new WarSystem(ctx);
  ctx.war = war;
  const insurgency = new InsurgencySystem(ctx);
  ctx.insurgency = insurgency;
  const labor = new LaborSystem(ctx);
  ctx.labor = labor;
  ctx.crime = new CrimeSystem(ctx);
  ctx.scanners = new ScannerSystem(ctx);
  ctx.roster = new RosterSystem(ctx);
  ctx.elections = new ElectionSystem(ctx);
  ctx.street = new StreetLifeSystem(ctx);
  ctx.families = new FamilySystem(ctx);
  ctx.security = new SecuritySystem(ctx);
  ctx.cwuHq = new CwuHqSystem(ctx);
  ctx.arsenal = new ArsenalSystem(ctx);
  ctx.prison = new PrisonSystem(ctx);
  ctx.shops = new StreetShops(ctx);
  ctx.housing = new Housing(ctx);
  ctx.fence = new Fence(ctx);
  ctx.gangs = new GangSystem(ctx);
  ctx.brawls = new Brawls(ctx);
  ctx.staffing = new Staffing(ctx);
  ctx.academy = new AcademySystem(ctx);
  ctx.academy.recruiting = opts.academyRecruiting ?? true;
  ctx.access = new Access(ctx);
  ctx.talk = new Talk(ctx);
  ctx.radio = new Radio(ctx);
  ctx.brawls.enabled = opts.brawlsEnabled ?? true;
  // Обратные связи систем: склад опустел — уведомить работников; закон советуется
  // с войной (комендантский час), доступом и штатным расписанием.
  economy.onEmpty = () => labor.noticeEmpty();
  law.curfewCheck = (c) => war.curfewViolation(c);
  law.panicking = (c) => c.panicUntil > law.now;
  law.trespass = (c) => ctx.access.trespassing(c);
  law.merit = (c, pts) => ctx.staffing.merit(c, pts);
  return {
    ctx,
    doors,
    law,
    economy,
    combat,
    underground: ctx.underground,
    war,
    insurgency,
    labor,
    crime: ctx.crime,
    scanners: ctx.scanners,
    roster: ctx.roster,
    elections: ctx.elections,
    street: ctx.street,
    families: ctx.families,
    security: ctx.security,
    cwuHq: ctx.cwuHq,
    arsenal: ctx.arsenal,
    prison: ctx.prison,
    shops: ctx.shops,
    housing: ctx.housing,
    fence: ctx.fence,
    gangs: ctx.gangs,
    routine: ctx.routine,
    errands: ctx.errands,
    brawls: ctx.brawls,
    academy: ctx.academy,
    staffing: ctx.staffing,
    access: ctx.access,
    radio: ctx.radio,
    talk: ctx.talk,
  };
}
